def totals_by_track(records):
    totals={}
    for row in records:
        track=row['track']
        minutes=row['minutes']
        if type(minutes) is not int or minutes<0:
            raise ValueError('minutes must be a non-negative integer')
        totals[track]=totals.get(track,0)+minutes
    return totals

